    if (innerParams3.y > 0.5) {
      color = applyBlendMode(color, innerColorParam.rgb, innerParams2.y);
      color = adjustBrightness(color, innerParams1.x);
      color = adjustContrast(color, innerParams1.y);
      color = adjustSaturation(color, innerParams1.z);
      color = adjustHue(color, innerParams1.w);
    } else {
      vec3 targetColor = innerColorParam.rgb;
      targetColor = adjustBrightness(targetColor, innerParams1.x);
      targetColor = adjustContrast(targetColor, innerParams1.y);
      targetColor = adjustSaturation(targetColor, innerParams1.z);
      targetColor = adjustHue(targetColor, innerParams1.w);
      color = targetColor;
    }
    if (innerParams3.x > 0.5 && innerParams2.x > 0.0) {
      float gradientFactor = 0.0;
      if (innerParams2.w < 0.5) {
        float angleRad = radians(innerParams2.z);
        vec2 gradientDir = vec2(cos(angleRad), sin(angleRad));
        vec2 centeredUV = uv - vec2(0.5);
        float projection = dot(centeredUV, gradientDir);
        gradientFactor = (projection + 0.707) / 1.414;
      } else {
        gradientFactor = length(uv - vec2(0.5)) * 2.0;
      }
      gradientFactor = clamp(gradientFactor, 0.0, 1.0);
      float innerStrength = innerParams2.x;
      float innerMixAmount = 0.0;
      if (innerStrength <= 0.5) {
        innerMixAmount = gradientFactor * (innerStrength * 2.0);
      } else {
        float enhanceFactor = (innerStrength - 0.5) * 2.0;
        innerMixAmount = gradientFactor + (gradientFactor * enhanceFactor * 0.5);
      }
      innerMixAmount = clamp(innerMixAmount, 0.0, 1.0);
      color = mix(color, innerGradientParam.rgb, innerMixAmount);
    }
    if (getBlendModeEnable(region) > 0.5) {
      color = applyBlendMode(color, getColor(region).rgb, getBlendMode(region));
      color = adjustBrightness(color, getBrightness(region));
      color = adjustContrast(color, getContrast(region));
      color = adjustSaturation(color, getSaturation(region));
      color = adjustHue(color, getHue(region));
    } else {
      color = adjustBrightness(color, getBrightness(region));
      color = adjustContrast(color, getContrast(region));
      color = adjustSaturation(color, getSaturation(region));
      color = adjustHue(color, getHue(region));
    }
    if (getGradientEnable(region) > 0.5 && getGradientStrength(region) > 0.0) {
      float gradientFactor = 0.0;
      vec2 regionUV = getRegionRelativeUV(uv, region);
      if (getGradientType(region) < 0.5) {
        float angleRad = radians(getGradientDirection(region));
        vec2 gradientDir = vec2(cos(angleRad), sin(angleRad));
        vec2 centeredRegionUV = regionUV - vec2(0.5);
        float projection = dot(centeredRegionUV, gradientDir);
        float regionDiagonal = 0.707;
        gradientFactor = (projection + regionDiagonal) / (regionDiagonal * 2.0);
      } else {
        gradientFactor = length(regionUV - vec2(0.5)) * 2.0;
      }
      gradientFactor = clamp(gradientFactor, 0.0, 1.0);
      float strength = getGradientStrength(region);
      float mixAmount = 0.0;
      if (strength <= 0.5) {
        mixAmount = gradientFactor * (strength * 2.0);
      } else {
        float enhanceFactor = (strength - 0.5) * 2.0;
        mixAmount = gradientFactor + (gradientFactor * enhanceFactor * 0.5);
      }
      mixAmount = clamp(mixAmount, 0.0, 1.0);
      color = mix(color, getGradientColor(region).rgb, mixAmount);
    }
  } else {
    color = applySingleLayerAdjustments(
      color, uv,
      getBrightness(region),
      getContrast(region),
      getSaturation(region),
      getHue(region),
      getColor(region),
      getGradientColor(region),
      getGradientStrength(region),
